 private final Activity activity;private final Handler main=new Handler(Looper.getMainLooper());private AlertDialog dialog;private LinearLayout rows;private ScrollView scroll;private Button check;private boolean running,rootBusy,updateBusy,rebindWaiting;private String rootStatus="ยังไม่ได้ตรวจสิทธิ์",updateStatus="ยังไม่ได้ตรวจอัปเดต",latestReport="";private int rootState=0;private final Runnable settle=()->{rebindWaiting=false;render();finishIfReady();};
