 private void show(){LinearLayout content=new LinearLayout(activity);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(20),dp(4),dp(20),dp(8));content.addView(text("Gozza Lalamove "+BuildConfig.VERSION_NAME+" · "+Build.MANUFACTURER+" "+Build.MODEL+" · Android "+Build.VERSION.RELEASE,12,AppTheme.muted(activity),false));check=new Button(activity);check.setText("ตรวจสอบและเชื่อมต่อใหม่");check.setAllCaps(false);check.setTextColor(AppTheme.onAccent(activity));check.setBackground(AppTheme.background(AppTheme.accent(activity),dp(5)));LinearLayout.LayoutParams button=new LinearLayout.LayoutParams(-1,dp(48));button.setMargins(0,dp(12),0,dp(8));content.addView(check,button);check.setOnClickListener(v->runChecks());scroll=new ScrollView(activity);rows=new LinearLayout(activity);rows.setOrientation(LinearLayout.VERTICAL);scroll.addView(rows);content.addView(scroll,new LinearLayout.LayoutParams(-1,Math.min(dp(410),(int)(activity.getResources().getDisplayMetrics().heightPixels*.51f))));dialog=new AlertDialog.Builder(activity).setTitle("ตรวจสอบระบบ").setView(content).setPositiveButton("ปิด",null).setNegativeButton("คัดลอกผล",(d,w)->activity.getSystemService(android.content.ClipboardManager.class).setPrimaryClip(ClipData.newPlainText("Gozza Lalamove",latestReport))).create();dialog.show();AppTheme.styleDialog(activity,dialog);check.setTextColor(AppTheme.onAccent(activity));dialog.setOnDismissListener(d->main.removeCallbacks(settle));render();}
 private boolean alive(){return dialog!=null&&dialog.isShowing()&&!activity.isFinishing()&&!activity.isDestroyed();}
 private StringBuilder report;
 private void row(String title,int state,String detail){row(title,state,detail,null);}
 private void row(String title,int state,String detail,Runnable action){String symbol=state>0?"✓":state<0?"✕":"—";int color=state>0?0xFF16A34A:state<0?0xFFDC2626:AppTheme.muted(activity);LinearLayout line=new LinearLayout(activity);line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(0,dp(10),0,dp(10));TextView icon=text(symbol,23,color,true);icon.setGravity(Gravity.CENTER);line.addView(icon,new LinearLayout.LayoutParams(dp(32),-2));LinearLayout labels=new LinearLayout(activity);labels.setOrientation(LinearLayout.VERTICAL);labels.addView(text(title,14,AppTheme.ink(activity),true));labels.addView(text(detail+(action!=null?" · ตั้งค่า ›":""),12,AppTheme.muted(activity),false));line.addView(labels,new LinearLayout.LayoutParams(0,-2,1));if(action!=null)line.setOnClickListener(v->action.run());rows.addView(line);View divider=new View(activity);divider.setBackgroundColor(AppTheme.divider(activity));rows.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));report.append(symbol).append(' ').append(title).append(": ").append(detail).append('\n');}
 private void permission(int step,String name){boolean ok=PermissionSetup.ready(activity,step);row(name,ok?1:-1,ok?"พร้อม":"ยังไม่ได้อนุญาต",ok?null:()->PermissionSetup.open(activity,step));}
 private void render(){if(!alive())return;int y=scroll.getScrollY();rows.removeAllViews();report=new StringBuilder("Gozza Lalamove "+BuildConfig.VERSION_NAME+"\n");permission(0,"สิทธิ์อ่านแจ้งเตือน");row("บริการอ่านแจ้งเตือน",JobListener.connected?1:PermissionSetup.reading(activity)&&rebindWaiting?0:-1,JobListener.connected?"เชื่อมต่อแล้ว":rebindWaiting?"รอ Android เชื่อมต่อบริการ":"ยังไม่เชื่อมต่อ");boolean floating=Store.prefs(activity).getBoolean("floatingEnabled",true);if(floating){permission(1,"สิทธิ์แสดงปุ่มลอย");row("ปุ่มลอย",JobListener.connected&&Settings.canDrawOverlays(activity)?1:0,JobListener.connected&&Settings.canDrawOverlays(activity)?"พร้อม · ซ่อนตามหน้าที่เปิดอยู่":"รอสิทธิ์หรือบริการอ่านแจ้งเตือน");}else row("ปุ่มลอย",0,"ผู้ใช้ปิดไว้");permission(2,"รู้ว่ากำลังเปิด Driver");permission(3,"แจ้งเตือนจาก Gozza Lalamove");permission(4,"ทำงานเบื้องหลัง");if(RootMode.enabled(activity)){row("สิทธิ์รูท",rootState,rootStatus);try{var info=activity.getPackageManager().getPackageInfo("com.gozza.lalamove",0);long code=Build.VERSION.SDK_INT>=28?info.getLongVersionCode():info.versionCode;boolean signature=activity.getPackageManager().checkSignatures(activity.getPackageName(),"com.gozza.lalamove")==PackageManager.SIGNATURE_MATCH;row("ส่วนเสริมอ่านงาน",RootSetup.moduleOutdated(code,signature)?-1:1,!signature?"ลายเซ็นไม่ตรง":code<RootSetup.REQUIRED_PROBE_CODE?"ต้องอัปเดตส่วนเสริม":"ติดตั้งรุ่นที่รองรับแล้ว");}catch(Exception error){row("ส่วนเสริมอ่านงาน",-1,"ไม่พบส่วนเสริม · เปิดโหมดรูทเพื่อตรวจการติดตั้ง");}row("ช่องทางเชื่อมต่อ",LocalRelayClient.connected()?1:0,LocalRelayClient.connected()?"เชื่อมต่อแล้ว":"กำลังรอช่องทางเชื่อมต่อ");row("ข้อมูลจาก Driver",DriverBridge.probeConnected()?1:0,DriverBridge.probeConnected()?"ได้รับสัญญาณล่าสุดแล้ว":"รอเปิดหน้า Driver · ยังไม่ถือว่าเชื่อมต่อเสีย");}else row("อ่านงานบนหน้า Driver (รูท)",0,"ผู้ใช้ปิดไว้");int update=updateStatus.startsWith("ใช้เวอร์ชัน")?1:updateStatus.startsWith("มีเวอร์ชัน")?-1:0;row("อัปเดตแอป",update,updateStatus);row("เปิดงานอัตโนมัติ",Store.prefs(activity).getBoolean("enabled",false)?1:0,Store.prefs(activity).getBoolean("enabled",false)?"เริ่มทำงานไว้":"ผู้ใช้ยังไม่เริ่มทำงาน");row("ปัดรับงานอัตโนมัติ",Store.prefs(activity).getBoolean("autoAccept",false)?1:0,Store.prefs(activity).getBoolean("autoAccept",false)?"เปิดไว้ · ไม่ทดสอบจากหน้านี้":"ผู้ใช้ปิดไว้");long received=Store.prefs(activity).getLong("lastReceived",0);row("งานเข้าล่าสุด",0,received==0?"ยังไม่มีแจ้งเตือนงาน":java.text.DateFormat.getDateTimeInstance().format(new java.util.Date(received)));latestReport=report.toString();issueSection();scroll.post(()->scroll.scrollTo(0,y));}
 private void issueSection(){TextView title=text("ข้อมูลปัญหาล่าสุด",16,AppTheme.ink(activity),true);title.setPadding(0,dp(18),0,dp(6));rows.addView(title);rows.addView(text(AppIssues.summary(activity),12,AppTheme.muted(activity),false));LinearLayout actions=new LinearLayout(activity);for(String name:new String[]{"ดูรายละเอียด","คัดลอก log"}){Button b=new Button(activity);b.setText(name);b.setAllCaps(false);b.setTextColor(AppTheme.accent(activity));actions.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));b.setEnabled(!AppIssues.report(activity).isEmpty());b.setOnClickListener(v->{if(name.equals("ดูรายละเอียด"))AppIssues.details(activity);else AppIssues.copy(activity);});}rows.addView(actions);}
 private void runChecks(){if(running)return;running=true;rebindWaiting=true;rootBusy=RootMode.enabled(activity);updateBusy=true;check.setEnabled(false);check.setText("กำลังตรวจสอบ…");if(PermissionSetup.reading(activity)&&!JobListener.connected)android.service.notification.NotificationListenerService.requestRebind(new ComponentName(activity,JobListener.class));JobListener.repairServices();updateStatus="กำลังตรวจอัปเดต…";Updates.checkNow(activity,status->{updateStatus=status;updateBusy=false;render();finishIfReady();});if(rootBusy){rootStatus="กำลังตรวจสิทธิ์…";rootState=0;Context c=activity.getApplicationContext();new Thread(()->{boolean root=checkRoot();main.post(()->{rootBusy=false;if(RootMode.enabled(c)){rootState=root?1:-1;rootStatus=root?"ได้รับสิทธิ์รูท":"ตรวจสิทธิ์ไม่สำเร็จ · ตรวจแอปจัดการรูท";if(root)LocalRelayClient.reconnect(c);}render();finishIfReady();});},"FullLock-diagnostic-root").start();}render();main.postDelayed(settle,1800);}
 private boolean checkRoot(){for(String[] args:new String[][]{{"su","-M","-c","id"},{"su","-c","id"}})try{java.lang.Process process=new ProcessBuilder(args).redirectErrorStream(true).start();if(!process.waitFor(4,TimeUnit.SECONDS)){process.destroyForcibly();continue;}byte[] data=new byte[1024];int n=process.getInputStream().read(data);if(process.exitValue()==0&&n>0&&new String(data,0,n,java.nio.charset.StandardCharsets.UTF_8).contains("uid=0"))return true;}catch(Exception ignored){}return false;}
 private void finishIfReady(){if(rootBusy||updateBusy||rebindWaiting)return;running=false;if(alive()){check.setEnabled(true);check.setText("ตรวจสอบและเชื่อมต่อใหม่");render();}}
